// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // Fuzz parameter: an array of addresses to pass as _tos.
    // The property: for ALL inputs the reference contract reverts when _tos.length == 0,
    // while the mutant (with require(_tos.length >= 0)) does not revert for that input.
    // We express this by calling transfer and observing whether it reverts (ok flag).
    function testFuzz_property(address[] memory tos) public {
        // keep domain wide; no restrictions
        bool ok;
        // call transfer and catch whether it reverts
        try c.transfer(address(0x123), address(0x456), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): reference always REVERTS when tos.length == 0,
        // so ok must be false for that case. The buggy mutant will make ok == true for that case.
        if (tos.length == 0) {
            assertTrue(!ok);
        } else {
            // when tos is non-empty the reference should succeed (it will attempt external calls and
            // may still revert if the callee fails; but given the public surface and EOA callees,
            // low-level calls to EOAs succeed, so transfer should return true). To avoid false
            // positives from arbitrary addresses, we accept either outcome for non-empty arrays,
            // and only enforce the empty-array behavior which distinguishes the mutant.
            assertTrue(true);
        }
    }
}
